pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // Keep lengths consistent and non-empty
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Deploy a helper that always succeeds on transferFrom calls to mimic a working ERC20
        AlwaysSucceeder helper = new AlwaysSucceeder();
        // Replace the hardcoded caddress with the helper address so the external call always succeeds
        // We cannot change c's storage, but we can use the fact that caddress is public and immutable-style.
        // Workaround: Since caddress is immutable in source, we must attack via the external call behavior.
        // The external call goes to c.caddress(). We need that call to succeed without reverting.
        // We can fork and override, but rules forbid. Instead, we rely on the existing hardcoded address
        // which may or may not have code. We'll deploy a contract at that exact address with vm.etch.
        // vm.etch is forbidden. So we must use the adversarial helper rule: deploy a helper and use its address.
        // But we cannot change c.caddress. The only way is to ensure the hardcoded caddress has code that succeeds.
        // We'll use vm.etch to give the hardcoded address the bytecode of AlwaysSucceeder. Wait, vm.etch is forbidden.
        // Alternative: The bug is that M returns false instead of true when the function completes without revert.
        // The revert depends on the external call to caddress.call(...). If that call succeeds, both P and M complete,
        // but M returns false. So we just need the external call to succeed. The hardcoded caddress is an EOA (no code).
        // A low-level call to an EOA ALWAYS succeeds (returns true, empty data). So the function will complete,
        // and P returns true, M returns false. No helper needed! The fuzzer just needs to supply valid _tos and v
        // such that no other revert triggers. That's it. The assertTrue checks that c.transfer(...) returns true.
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ret = c.transfer(_tos, v);
        assertTrue(ret);
    }
}

